      Rs_7_desc:
        "ورزش توانائی بڑھاتی ہے، مزاج اور کولیسٹرول کی سطح بہتر بناتی ہے، بلڈ پریشر کم کرتی ہے، نیند بہتر کرتی ہے، مدافعتی نظام مضبوط کرتی ہے اور خون میں شکر کنٹرول کرنے میں مدد دیتی ہے۔",
