      Rs_PotentialAge: "גיל הבריאות הפוטנציאלי",
      Rs_HealthyHabitsParagraph:
        "מספר מחקרים גדולים, כולל מחקר מחוז אלמידה הידוע ומחקרי הבריאות של האדוונטיסטים, חושפים קשר ברור בין הרגלי הבריאות המפורטים למטה לבין הסיכון למחלה או למוות. אנשים שמקפידים על כל ההרגלים הבריאים הללו עשויים להשפיע על אורך חייהם בכמעט 30 שנים.",
      Rs_MedicalDisclaimerTitle: "הצהרה רפואית",
      Rs_MedicalDisclaimerText:
        "גיל הבריאות מיועד למטרות מידע וחינוך בלבד. אין מדובר באבחנה רפואית ואין להשתמש בו כתחליף לייעוץ, אבחון או טיפול רפואי מקצועי. יש להתייעץ תמיד עם איש מקצוע רפואי מוסמך לפני קבלת החלטות רפואיות או שינוי בטיפול הרפואי שלך.",
      Rs_MedicalSources: "מקורות רפואיים",
      Rs_Source: "מקור",
      Rs_Recommendations: "המלצות",
      Rs_1_title: "אכול ארוחת בוקר טובה מדי יום",
      Rs_1_desc:
        "ארוחת הבוקר ממריצה את חילוף החומרים, עוזרת לריכוז ומשפרת את התפקוד בבית הספר ובעבודה. היא גם מסייעת בשמירה על משקל בריא.",
      Rs_2_title: "הימנע מנשנושים",
      Rs_2_desc:
        "נשנושים יכולים להוסיף בממוצע 580 קלוריות ביום, לפגוע בעיכול, להפריע לשליטה ברמת הסוכר בדם ולתרום לעלייה במשקל.",
      Rs_3_title: "הרבה יותר בפירות וירקות",
      Rs_3_desc:
        "פירות וירקות עשירים בפיטוכימיקלים, ויטמינים וסיבים, והם גם דלים יותר בקלוריות.",
      Rs_4_title: "הגדל את צריכת הדגנים המלאים",
      Rs_4_desc:
        "דגנים מלאים מכילים סיבים, ויטמיני B ומינרלים חיוניים התומכים בבריאות הכללית.",
      Rs_5_title: "אכול יותר אגוזים",
      Rs_5_desc:
        "אגוזים הם מקור מצוין לחלבון ולשומנים בריאים, והם עוזרים לווסת את רמות הסוכר בדם.",
      Rs_6_title: "הימנע מבשר אדום",
      Rs_6_desc:
        "אכילת בשר אדום נקשרה לסוכרת מסוג 2, מחלות לב, שבץ וסוגי סרטן מסוימים.",
      Rs_7_title: "התעמל בקביעות",
      Rs_7_desc:
        "פעילות גופנית מעלה את האנרגיה, משפרת את מצב הרוח ואת רמות הכולסטרול, מורידה את לחץ הדם, משפרת את השינה, מחזקת את המערכת החיסונית ועוזרת לשלוט ברמות הסוכר בדם.",
      Rs_8_title: "השג משקל בריא",
      Rs_8_desc:
        "שמור על מדד מסת גוף בין 18.5 ל-24.9 ועל היקף מותן בריא (פחות מ-40 אינץ' לגברים, 35 אינץ' לנשים).",
      Rs_9_title: "קבל 7-8 שעות שינה טובות כל לילה",
      Rs_9_desc:
        "שינה מספקת תומכת בזיכרון, בלמידה, בחילוף החומרים ובתפקוד המערכת החיסונית.",
      Rs_10_title: "הפסק לעשן",
      Rs_10_desc:
        "עישון פוגע בכל איבר בגוף ומגביר את הסיכון לסרטן, מחלות לב, מחלת ריאות חסימתית כרונית (COPD), אסטמה ובעיות שיניים.",
      Rs_11_title: "אל תשתה אלכוהול",
      Rs_11_desc:
        "שימוש באלכוהול עלול לגרום לבעיות נוירולוגיות, קרדיווסקולריות ופסיכיאטריות, וכן להעלות את הסיכון לסרטן ולמחלות כבד.",
      Rs_12_title: "הגבר את הרוחניות",
      Rs_12_desc:
        "אמונה באלוהים עשויה לשפר את הבריאות הנפשית ולחזק את תפקוד המערכת החיסונית.",
      Rs_SavePdf: "שמור pdf",
      Rs_ShareReport: "שתף דוח",

